solution.solution.cpp:
#include <memory>
#include <vector>

class Animal
{
public:
    virtual ~Animal() = default;
};

class Dog : public Animal
{
public:
    explicit Dog(int tricks) : m_tricks{ tricks } {}
    int tricks() const { return m_tricks; }

private:
    int m_tricks{};
};

class Cat : public Animal {};

Dog* asDog(Animal* animal)
{
    return dynamic_cast<Dog*>(animal);
}

int totalTricks(const std::vector<std::unique_ptr<Animal>>& animals)
{
    int total{ 0 };
    for (const auto& animal : animals)
    {
        if (const Dog* dog{ dynamic_cast<const Dog*>(animal.get()) })
        {
            total += dog->tricks();
        }
    }
    return total;
}

unitTests:
TEST("asDog") { Dog d{ 3 }; Cat c{}; CHECK(asDog(&d) == &d); CHECK(asDog(&c) == nullptr); CHECK(asDog(nullptr) == nullptr); }
TEST("totalTricks counts only the dogs") {
    std::vector<std::unique_ptr<Animal>> v;
    v.push_back(std::make_unique<Dog>(3));
    v.push_back(std::make_unique<Cat>());
    v.push_back(std::make_unique<Dog>(5));
    CHECK_EQ(totalTricks(v), 8);
    CHECK_EQ(totalTricks(std::vector<std::unique_ptr<Animal>>{}), 0);
}

